      "path": "packages/dsh/src/gates/dispatch.ts",
      "content": "/**\n * Dispatch gate — subagent delegation gating on `tools/pre-execute` (plan\n *   §11 extraction).\n *\n * The `tools/pre-execute` listener (`preExecuteListener`, registered by the\n * entry `apply` with `prepend`) runs the engine's SINGLE dispatch-gate\n * composition (shape guard + field gate + anti-recursion + default-branch\n * gate + header-region enforcement — opencode parity) plus the dsh-side\n * additions (worktree L1/L2 checks). The host adapter's `beforeDispatch`\n * hook shares the SAME core (`dispatchGateCore`) and the lease gate joins\n * the exec-bound listener path (`leaseGateViolations`).\n *\n * Module boundary: no barrel — the entry and the adapter import by explicit\n * relative path; public exports (`DispatchGateAdvisory`) are re-exported\n * verbatim by the entry.\n */\nimport { existsSync } from 'node:fs'\nimport { basename, join, resolve } from 'node:path'\nimport { type Context } from '@deepseek-ai/cordis'\nimport {\n  applyEnforcement,\n  assignmentHeaderRegion,\n  collectActiveLifecycleBranches,\n  readExecutionState,\n  composeDispatchGate,\n  executionModeToN,\n  isReadOnlyAssignmentRole,\n  l1PreDispatchCheck,\n  l2PreDispatchCheck,\n  parseAssignmentBranchForms,\n  parseAssignmentFields,\n  parseEnforcementFlag,\n  probeCheckoutRoot,\n  readMainWorktree,\n  resolveRepoEnforcement,\n} from '@mstar-harness/engine'\nimport type {\n  AssignmentFields,\n  GateResult,\n  ValidationResult,\n  WorkflowSnapshot,\n  WorktreeTrack,\n} from '@mstar-harness/engine'\nimport type { PreToolDecision, ToolExecution } from '@deepseek-ai/dsh-tools'\nimport { STATUS_FILE, asRecord, formatViolation, HarnessResolver, ROOT_SESSION_DISPATCH_BINDING, liveConfigValue } from './_shared.ts'\nimport type { Config, SessionHintRead } from './_shared.ts'\n// The root discriminator (`session.header.parentSession === undefined`) the\n// planMode bridge already reads: the dispatch gate reuses ONE lineage grammar\n// instead of keeping a second root test.\nimport { isRootLikeAgent } from './steering.ts'\n// Type-only (erased at runtime): the carrying-session hint the gate forwards\n// to the shared resolver.\nimport type { SessionHint } from './workflow-selection.ts'\n// v3 read: the plan rows + leases live on the ACTIVE workflow snapshot\n// (`workflows/<id>/snapshot.json` — the v1 root `plans[]` home is gone).\n// The dispatch gates are WRITE-path-adjacent (lease re-verify, worktree\n// L1, P-b attribution), so they use the ACTIVE-SET resolver only — the\n// terminal-mtime fallback stays catalog-read-only.\nimport {\n  activeRowsOf,\n  readExecutionWorkflowSource,\n  refusalOf,\n} from './workflow-selection.ts'\nimport type { ExecutionWorkflowSourceRead } from './workflow-selection.ts'\n// The P-a/P-c policy + cache + the SHARED name normalization (plan\n//   Task 2 — the SINGLE four-tier decision point;\n// this module maps the verdict to the PreToolDecision refusal vocabulary).\n// `normalizeWorkflowName` is the Task 5 congruence fold-in: the gate composes\n// `metaName` through the SAME function the run-start observation keys the\n// ask cache with (workflow-ledger.ts), so a control-char name gates and\n// observes under one key. workflow-policy imports THIS module type-only\n// (`WorkflowGateInput` — erased at runtime), so the value edge is one-way:\n// no runtime cycle.\nimport { normalizeWorkflowName, workflowPolicy } from './workflow-policy.ts'\n// Type-only (erased at runtime — no cycle): the P-c cache class, referenced\n// by the gateWorkflow doc (`WorkflowAskCache.record` — the answer seam).\nimport type { WorkflowAskCache } from './workflow-policy.ts'\n// Type-only (erased at runtime — no cycle): the adapter owns the shared\n// dispatch-gate core and is constructed by the entry `apply`; the listener\n// signatures type their adapter parameter through the adapter module.\nimport type { DshHostAdapter } from './adapter.ts'\n// Type-only (erased at runtime — no cycle): the durable workflow-verdict\n// ledger vocabulary. The RECORD goes through the adapter method (it imports\n// agent-flow values) — dispatch.ts itself stays free of a runtime\n// agent-flow edge (the ledger imports dispatch helpers).\nimport type { WorkflowVerdict } from './agent-flow.ts'\n/** Logger label for the dispatch gate (dsh logger naming: `<scope>/<subject>`). */\nexport const DISPATCH_LOGGER = 'mstar/dispatch-gate'\n\n/**\n * Default delegation tool names the dispatch gate matches (tool-subagent\n * default id + its fork sibling — roadmap §9 W-B1: fork dispatches carry the\n * same Assignment-shaped `{ description, prompt }` args and must be gated\n * like `subagent`). Exported SHARED with the agent-flow settle pairing\n * (`registerSettleListener` matches the same tool set) so the default cannot drift between\n * the gate and the settle seam.\n */\nexport const DEFAULT_DISPATCH_TOOLS = ['subagent', 'subagent_fork'] as const\n\n/**\n * The fixed workflow/ralph tool names the workflow gate matches (plan\n *   — architect-verified): the workflow tool\n * registers under Config-default name `'workflow'` and is RENAMEABLE per\n * instance (`toolName`, `tool-workflow/src/index.ts:41`); `ralph` is a\n * fixed name (`tool-ralph/src/index.ts:413`). A renamed instance is out\n * of reach until its name is configured — the same documented caveat as\n * `DEFAULT_DISPATCH_TOOLS`. The workflow tools are gated by THEIR OWN\n * branch, never by addition to `DEFAULT_DISPATCH_TOOLS` (plan Global\n * Constraint — that list stays `['subagent', 'subagent_fork']`).\n */\nexport const DEFAULT_WORKFLOW_TOOLS = ['workflow', 'ralph'] as const\n\n/**\n * The fixed dsh Agent Teams tool names the dispatch gate matches, mapped to\n * the argument field that carries the Assignment-shaped text (the installed\n * `@deepseek-ai/dsh-experimental-tool-agent-team` 0.2.1-rc.2 surface:\n * `spawn_teammate.prompt`, `team_task_create.description`,\n * `team_task_update.description`, `send_message.message`).\n *\n * The team tools are gated by THEIR OWN branch, never by addition to\n * `DEFAULT_DISPATCH_TOOLS` (that list stays `['subagent', 'subagent_fork']`).\n * `team_task_update.description` is OPTIONAL upstream — a status-only\n * `claim`/`release`/`complete` update carries no carrier at all — so a\n * missing (or non-string) carrier is no gate decision, exactly like a\n * missing `prompt` on `subagent`. The tools are fixed names, so no Config\n * key is added for them; a RENAMED instance is out of reach until its name\n * is added here — the same documented caveat `DEFAULT_DISPATCH_TOOLS`\n * carries for renamed subagent instances.\n */\nexport const TEAM_DISPATCH_TOOLS = {\n  spawn_teammate: 'prompt',\n  team_task_create: 'description',\n  team_task_update: 'description',\n  send_message: 'message',\n} as const\n\n/** Tool names the Agent Teams branch owns (keys of {@link TEAM_DISPATCH_TOOLS}). */\ntype TeamDispatchTool = keyof typeof TEAM_DISPATCH_TOOLS\n\n/**\n * True when `name` is one of the fixed Agent Teams carriers. `Object.hasOwn`\n * keeps prototype keys (`constructor`, `__proto__`) out of the map read.\n */\nfunction isTeamDispatchTool(name: string): name is TeamDispatchTool {\n  return Object.hasOwn(TEAM_DISPATCH_TOOLS, name)\n}\n\n/** `## Assignment` heading marker (opencode parity — shape guard only). */\nconst ASSIGNMENT_HEADING_RE = /^#{1,6}\\s+Assignment\\s*$/m\n\n/** Shape-guard match of an Assignment header field (opencode parity). */\nconst ASSIGNMENT_FIELD_RE =\n  /^[ \\t]*(?:[-*][ \\t]+)?\\*{0,2}(Execute as|Delegation|Task category)\\*{0,2}[ \\t]*:[ \\t]*(\\S.*)$/gm\n\n/**\n * Advisory emitted on warn-mode dispatch-gate passes (the * `mstar/status-gate` decision reused for the dispatch gate — dsh's\n * `agent/status` lifecycle event stays untouched). Consumers (later tasks,\n * catalogs) observe this event for model-visible/session-log surfacing.\n */\nexport interface DispatchGateAdvisory {\n  /** The matched delegation tool name. */\n  tool: string\n  /** The Assignment's declared `Execute as` ('' when missing). */\n  role: string\n  /** The gate verdict (warn-mode: `hardBlocked` is false). */\n  result: GateResult\n  /** Whether hard enforcement is on (advisory events are warn-mode by construction). */\n  hard: boolean\n  /** True when the gate errored internally and degraded to allow (structured degraded advisory). */\n  degraded?: boolean\n}\n\n/**\n * True when the text looks like an Assignment (opencode parity: `## Assignment`\n * heading or at least one core field line). Non-Assignment delegation prompts\n * stay silent — no false-positive warnings. Callers MUST pass the engine\n * `assignmentHeaderRegion` slice: a `## Assignment` heading or\n * field line quoted in the task body must not shape a non-assignment prompt.\n * Exported for the agent-flow ledger's shape guard — the shared\n * `DshHostAdapter.dispatchGate` core applies the SAME guard on both dispatch\n * surfaces, so the exec-less host-hook path records nothing for\n * non-Assignment text either).\n */\nexport function isAssignmentShaped(assignmentText: string): boolean {\n  return ASSIGNMENT_HEADING_RE.test(assignmentText) || assignmentText.match(ASSIGNMENT_FIELD_RE) !== null\n}\n\n/**\n * Resolve the hard-enforcement flag for one dispatch: explicit Config override\n * wins, else the Assignment's OWN `Enforcement: hard` header flag (opencode\n * parity — header region only, a body-quoted example never hardens), else the\n * repo `.mstarc` `[config] enforcement`, else the iteration compass\n * frontmatter, else warn-only.\n */\nexport function resolveDispatchHard(harnessDir: string | null, config: Config, assignmentText: string): boolean {\n  if (config.enforcement === 'hard') return true\n  if (config.enforcement === 'soft') return false\n  if (parseEnforcementFlag(assignmentHeaderRegion(assignmentText)).hard) return true\n  return harnessDir !== null && resolveRepoEnforcement(harnessDir).hard\n}\n\n/** The hard-mode veto reason: one line per violation + the refusal channel. */\nfunction denyReason(tool: string, verdict: GateResult): string {\n  return [\n    `subagent dispatch (${tool}) blocked by Enforcement: hard — the Assignment fails the dispatch gate`,\n    ...verdict.violations.map(formatViolation),\n    'refusal channel: tools/pre-execute PreToolDecision { kind: \\'deny\\' }; skill: mstar-dispatch-gates',\n  ].join('\\n')\n}\n\n/**\n * One lease-gate violation line (dsh-side codes live in the `lease.dispatch.*`\n * namespace; the engine emits `lease.verify.*` / `lease.execution-lease.*`).\n */\nfunction leaseViolation(code: string, message: string, fix?: string): ValidationResult {\n  return { ok: false, severity: 'high', code, message, fix }\n}\n\n\n/**\n * Parse one Assignment HEADER-REGION field value with the engine\n * `parseAssignmentFields` semantics: a `**Field**: value` (bold) or\n * `Field: value` (plain) line, optionally list-bulleted, at line start.\n * Returns the trimmed value or undefined when the field is absent/empty.\n *\n * Callers MUST pass the engine `assignmentHeaderRegion(assignmentText)` slice\n * The engine owns the header/body boundary, so\n * body-quoted field examples after a `# Task` / `# Target` / `---` marker\n * never leak into header fields — the same discipline `resolveDispatchHard`\n * already honors for the Enforcement flag. This module keeps no second\n * grammar for the boundary.\n *\n * @param headerRegion - `assignmentHeaderRegion(assignmentText)`, never the raw text.\n * @param label - the header field label to read (e.g. `Plan Path`).\n */\nfunction assignmentHeaderValue(headerRegion: string, label: string): string | undefined {\n  const escaped = label.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n  const bold = new RegExp(`^[ \\\\t]*(?:[-*][ \\\\t]+)?\\\\*\\\\*\\\\s*${escaped}\\\\s*\\\\*\\\\*[ \\\\t]*:[ \\\\t]*(.*)$`, 'm')\n  const plain = new RegExp(`^[ \\\\t]*(?:[-*][ \\\\t]+)?${escaped}[ \\\\t]*:[ \\\\t]*(.*)$`, 'm')\n  const line = headerRegion.match(bold)?.[1] ?? headerRegion.match(plain)?.[1]\n  if (line === undefined) return undefined\n  const value = stripWrappingCodeSpan(line.trim())\n  return value === '' ? undefined : value\n}\n\n/**\n * Strip ONE wrapping markdown code span from a header value.\n *\n * Assignment prose routinely writes header values as code spans —\n * ``**Plan Path**: `/x/plan.md` `` — and the extractor used to keep the\n * backticks. That failed **silently**: `planIdOf` keys off a literal `.md`\n * suffix, so `` plan.md` `` was not recognised as a plan file and the id was\n * carried into the agent-flow ledger *with* its trailing backtick, matching no\n * registered plan (and, under an iteration lease gate, producing a spurious\n * \"plan is not registered\" violation).\n *\n * Only a single clean pair is stripped: a value that wraps several spans\n * (`` `/a`, `/b` ``) has backticks inside and is left untouched, so no other\n * reading of the line changes.\n * @param value - the trimmed header value.\n * @returns the value without one wrapping pair of backticks.\n */\nfunction stripWrappingCodeSpan(value: string): string {\n  if (value.length < 2 || !value.startsWith('`') || !value.endsWith('`')) return value\n  const inner = value.slice(1, -1)\n  return inner.includes('`') ? value : inner.trim()\n}\n\n/** First whitespace-delimited token of a header value (paths in this convention never contain spaces). */\nfunction firstToken(value: string): string | undefined {\n  const token = value.split(/\\s+/)[0]\n  return token === '' ? undefined : token\n}\n\n/**\n * ALL header-region values of a repeated Assignment field label (bold or\n * plain, optionally list-bulleted — the same line grammar as the engine\n * `parseAssignmentFields`). Repeated `Worktree path` / `Working branch`\n * lines declare the L2 parallel-track context; empty values are\n * dropped (consistent with {@link assignmentHeaderValue}: an empty line is\n * an absent field, never a malformed track).\n *\n * Callers MUST pass the engine `assignmentHeaderRegion(assignmentText)`\n * slice: body-quoted field examples after a\n * `# Task` / `# Target` / `---` marker never leak into the track\n * declarations — the same header-region discipline the dispatch gate\n * already honors.\n * @param headerRegion - `assignmentHeaderRegion(assignmentText)`, never the raw text.\n * @param label - the header field label to read (e.g. `Worktree path`).\n */\nfunction assignmentHeaderValues(headerRegion: string, label: string): string[] {\n  const escaped = label.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n  const bold = new RegExp(`^[ \\\\t]*(?:[-*][ \\\\t]+)?\\\\*\\\\*\\\\s*${escaped}\\\\s*\\\\*\\\\*[ \\\\t]*:[ \\\\t]*(.*)$`)\n  const plain = new RegExp(`^[ \\\\t]*(?:[-*][ \\\\t]+)?${escaped}[ \\\\t]*:[ \\\\t]*(.*)$`)\n  const values: string[] = []\n  for (const line of headerRegion.split(/\\r?\\n/)) {\n    const raw = (line.match(bold) ?? line.match(plain))?.[1]\n    const value = raw === undefined ? undefined : stripWrappingCodeSpan(raw.trim())\n    if (value !== undefined && value !== '') values.push(value)\n  }\n  return values\n}\n\n/** A header value that means \"no value\" (placeholder conventions). Type guard so callers narrow to `string`. Shared with the agent-flow ledger  (one grammar, no copy-paste drift). */\nexport function isNaValue(value: string | undefined): value is undefined {\n  return value === undefined || /^(?:n\\/?a|none)$/i.test(value)\n}\n\n/**\n * Resolve the target plan id from the Assignment HEADER region: `Plan Path`\n * basename (`.md` stripped), else `SDD dir` basename, else a `plan_id` field.\n * Exported for the agent-flow ledger's dispatch derivation (the ledger\n * records the same plan identity the gate resolved — one grammar).\n * @param headerRegion - `assignmentHeaderRegion(assignmentText)` (\n * only the header is read — a plan path quoted in the task body never\n * resolves a plan id).\n */\nexport function planIdOf(headerRegion: string): string | undefined {\n  const planPath = assignmentHeaderValue(headerRegion, 'Plan Path')\n  if (!isNaValue(planPath)) {\n    const id = basename(firstToken(planPath) ?? '')\n    return id.endsWith('.md') ? id.slice(0, -3) : id\n  }\n  const sddDir = assignmentHeaderValue(headerRegion, 'SDD dir')\n  if (!isNaValue(sddDir)) {\n    const id = basename(firstToken(sddDir) ?? '')\n    return id === '' ? undefined : id\n  }\n  const planId = assignmentHeaderValue(headerRegion, 'plan_id')\n  return isNaValue(planId) ? undefined : planId\n}\n\n/**\n * The dispatching session's stable id, when the seam exposes it (dsh\n * Agent.id). Exported for the agent-flow ledger's dispatch derivation (the\n * ledger records the same agent identity the lease gate compares — one\n * grammar).\n */\nexport function sessionIdOf(exec: ToolExecution): string | undefined {\n  const agent = asRecord(exec.agent)\n  const id = agent?.id\n  return typeof id === 'string' && id.trim() !== '' ? id : undefined\n}\n\n/**\n * Lease gate — ADDITIVE beyond the opencode parity field set:\n * opencode's `validateDispatchAssignment` does NOT run lease checks at\n * dispatch, so every violation emitted here is dsh-only and clearly scoped:\n * the check fires ONLY for WRITABLE dispatches whose Assignment declares\n * `Execution mode: sdd` (engine `executionModeToN` semantics — sdd maps to\n * N=3; the function's violation path is intentionally unused so\n * `dispatch.execution-mode.*` codes stay out of the parity field set) OR\n * whose plan row is `InProgress`.\n *\n * Contract (status-and-residuals.md § Pre-dispatch re-verify; v3\n * relocation —): before any\n * writable implement dispatch, reread the ACTIVE workflow snapshot\n * (`workflows/<id>/snapshot.json` — the v1 root `plans[]` home is gone; the\n * root v2 `status.json` supplies the active `workflows[]`) and confirm the\n * session dispatches into the row's own recorded scope — `worktree_path` and\n * `working_branch` must match the Assignment; mismatch or an unrecorded scope\n * → STOP.\n *\n * Degrade-allow cases (no false positives): no harness dir, unresolvable plan\n * id, and non-SDD assignments whose plan row is absent or not InProgress.\n * Unverifiable states (unreadable/missing root status.json, a\n * selection failure — v1/migration-required root, no active workflow — an\n * unreadable/missing snapshot, plan row not registered) are violations ONLY\n * for sdd dispatches (the lease state cannot be confirmed — the status gate\n * already guards the next write); unreadable docs never harden a soft\n * workflow. A missing status.json is NOT a silent fail-open for sdd: the\n * row's recorded scope, and a missing root/snapshot cannot confirm it —\n * `lease.dispatch.unverifiable` fires (advisory in warn, deny under hard).\n * @param hint - the carrying session's selection hint: it decides WHICH\n *   active lifecycle's snapshot the lease is re-verified against, so a\n *   session that is not bound to the lifecycle holding the plan row stops\n *   with `lease.dispatch.plan-not-found` instead of verifying a lease it\n *   does not own.\n */\nexport async function leaseGateViolations(\n  harnessDir: string | null,\n  exec: ToolExecution,\n  writable: boolean | undefined,\n  prompt: string,\n  hint?: SessionHint,\n  activeSource?: ExecutionWorkflowSourceRead,\n): Promise<ValidationResult[]> {\n  if (harnessDir === null || writable === false) return []\n  const header = assignmentHeaderRegion(prompt)\n  const mode = assignmentHeaderValue(header, 'Execution mode')\n  const sdd = executionModeToN(mode ?? '').n === 3\n  const planId = planIdOf(header)\n  if (planId === undefined || planId === '') return []\n  let source: ExecutionWorkflowSourceRead\n  try {\n    // The Assignment names its plan row: that row belongs to exactly one ACTIVE\n    // lifecycle, so it identifies the lifecycle even when several are active and\n    // the cwd cannot discriminate (parallel worktrees under one control root).\n    const selectionHint = { ...hint, planId }\n    source = activeSource ?? await readExecutionWorkflowSource({ harnessDir }, selectionHint)\n  } catch {\n    return [leaseViolation('lease.dispatch.unverifiable', 'the ACTIVE execution workflow could not be read; STOP before writable dispatch', 'restore the ACTIVE store authority, then rerun the dispatch')]\n  }\n  if (source.kind !== 'active') {\n    if (!sdd && source.kind === 'error' && source.selection.kind === 'error' && source.selection.code === 'workflow.selection.no-active') return []\n    return [leaseViolation(\n      'lease.dispatch.unverifiable',\n      source.kind === 'unavailable' ? source.message : 'the ACTIVE workflow could not be selected',\n      'initialize or upgrade the ACTIVE store, then register the workflow and prepare the plan before dispatch',\n    )]\n  }\n  const row = activeRowsOf(source.snapshot).find((candidate) => candidate?.id === planId || candidate?.plan_id === planId)\n  if (row === undefined) return sdd ? [leaseViolation('lease.dispatch.plan-not-found', `plan ${planId} is not registered in ACTIVE workflow ${source.workflowId}`, 'register the plan row in the workflow and run `mstar plan prepare` before writable dispatch')] : []\n  if (!sdd && row.status !== 'InProgress') return []\n  const metadata = asRecord(row.metadata)\n  const rowWorktreePath = typeof metadata?.worktree_path === 'string' ? metadata.worktree_path : ''\n  const rowWorkingBranch = typeof metadata?.working_branch === 'string' ? metadata.working_branch : ''\n  const violations: ValidationResult[] = []\n  if (rowWorktreePath === '' || rowWorkingBranch === '') {\n    violations.push(leaseViolation('lease.dispatch.unverifiable', `plan ${planId} has no recorded worktree/branch scope in ACTIVE workflow ${source.workflowId}`, 'record the row scope through `mstar plan prepare --worktree-path <abs> --working-branch <name>` before writable dispatch'))\n  } else {\n    const worktree = assignmentHeaderValue(header, 'Worktree path')\n    const wt = worktree === undefined ? undefined : firstToken(worktree)\n    if (isNaValue(wt) || resolve(wt) !== resolve(rowWorktreePath)) violations.push(leaseViolation('lease.dispatch.worktree-mismatch', 'Assignment Worktree path does not match the ACTIVE plan row scope', 'set the absolute Worktree path to the row metadata worktree_path'))\n    const forms = parseAssignmentBranchForms(header)\n    const branch = forms.createForm?.name ?? forms.workingBranch ?? forms.directOn?.branch\n    if (branch !== undefined && branch !== rowWorkingBranch) violations.push(leaseViolation('lease.dispatch.branch-mismatch', 'Assignment Working branch does not match the ACTIVE plan row scope', 'set Working branch to the row metadata working_branch'))\n  }\n  return violations\n}\n\n/**\n * One worktree-gate violation line (dsh-side codes live in the\n * `worktree.l2.*` namespace beside the engine's `worktree.l1.*` /\n * `worktree.l2.*` emit).\n */\nfunction worktreeViolation(code: string, message: string, fix?: string): ValidationResult {\n  return { ok: false, severity: 'high', code, message, fix }\n}\n\n/**\n * L2 within-plan track isolation (engine `l2PreDispatchCheck`):\n * when the Assignment declares parallel tracks — ≥2 `Worktree path` header\n * entries, or the documented parallel-tracks marker (`Dispatch mode:\n * parallel independent tracks`, mstar-phase-gates 并行标签 /\n * parallel-writable-pre-dispatch.md step 5) — every declared track must\n * carry an absolute, distinct worktree path whose checkout branch matches\n * its Working branch, BEFORE the first concurrent writable dispatch\n * (N parallel invokes ≠ isolation).\n *\n * Track pairing follows the Assignment grammar: one `Working branch` entry\n * per `Worktree path`, OR a single `Working branch` line applying to every\n * track (the same-branch multi-dir topology, mstar-branch-worktree\n * 同分支多目录例外 — git forbids one branch in two linked worktrees, so the\n * second checkout is a clone). Any other count mismatch is a violation.\n *\n * Pure over the header + the filesystem; the engine probes\n * `git -C <path> branch --show-current` per valid track (bounded, fails\n * closed). Header-region scoping: the caller passes the engine\n * `assignmentHeaderRegion` slice only.\n * @param header - `assignmentHeaderRegion(assignmentText)`.\n */\nfunction worktreeL2Violations(header: string): ValidationResult[] {\n  const worktreePaths = assignmentHeaderValues(header, 'Worktree path')\n  const workingBranches = assignmentHeaderValues(header, 'Working branch')\n  const dispatchMode = assignmentHeaderValue(header, 'Dispatch mode')\n  // Parallel-track declaration: ≥2 Worktree path entries, or the documented\n  // canonical parallel-tracks marker (`Dispatch mode: parallel independent\n  // tracks`, mstar-phase-gates 并行标签). A single Worktree path is the\n  // serial norm and never triggers the L2 checklist (no track list to verify\n  // against). The marker match is exact (P3 T2 review — no substring\n  // widening): a Dispatch mode merely CONTAINING \"parallel\" (e.g. a serial\n  // mode with a parallel-flavored name) must not trigger the L2 checklist.\n  const isParallelTracksMarker = dispatchMode?.trim().toLowerCase() === 'parallel independent tracks'\n  if (worktreePaths.length < 2 && !isParallelTracksMarker) return []\n\n  const violations: ValidationResult[] = []\n  const tracks: WorktreeTrack[] = []\n  if (worktreePaths.length === 0 || workingBranches.length === worktreePaths.length) {\n    for (let i = 0; i < worktreePaths.length; i += 1) {\n      tracks.push({ worktreePath: worktreePaths[i]!, workingBranch: workingBranches[i] ?? '' })\n    }\n  } else if (workingBranches.length === 1) {\n    // One Working branch line applies to every track (同分支多目录例外).\n    for (const path of worktreePaths) tracks.push({ worktreePath: path, workingBranch: workingBranches[0]! })\n  } else {\n    violations.push(worktreeViolation(\n      'worktree.l2.track-count-mismatch',\n      `parallel-track declaration pairs ${worktreePaths.length} Worktree path entr${worktreePaths.length === 1 ? 'y' : 'ies'} with ${workingBranches.length} Working branch entries — every track needs its own absolute Worktree path AND Working branch (or one shared branch for all tracks)`,\n      'align the track counts in the Assignment header (one Worktree path + Working branch per track, or a single Working branch for all tracks)',\n    ))\n    const n = Math.min(worktreePaths.length, workingBranches.length)\n    for (let i = 0; i < n; i += 1) {\n      tracks.push({ worktreePath: worktreePaths[i]!, workingBranch: workingBranches[i]! })\n    }\n  }\n  const isolation = l2PreDispatchCheck({ tracks })\n  violations.push(...isolation.violations)\n  if (!isolation.ok) return violations\n  const checkoutRoots = new Set<string>()\n  for (const track of tracks) {\n    const root = probeCheckoutRoot(track.worktreePath)\n    if (root === null) {\n      violations.push(worktreeViolation(\n        'worktree.l2.checkout-unresolved',\n        `cannot establish the Git checkout root of \"${track.worktreePath}\" before writable dispatch`,\n        'use an existing Git worktree checkout on its declared Working branch and retry dispatch',\n      ))\n    } else if (checkoutRoots.has(root)) {\n      violations.push(worktreeViolation(\n        'worktree.l2.checkout-collision',\n        `parallel writable track \"${track.worktreePath}\" shares Git checkout \"${root}\" with another track; subdirectories and symlink aliases are not independent worktrees`,\n        'create a separate Git worktree for each writable track and update its Worktree path before retrying dispatch',\n      ))\n    } else {\n      checkoutRoots.add(root)\n    }\n  }\n  return violations\n}\n\n/**\n * The selected ACTIVE workflow graph for synchronous dispatch consumers.\n * `readExecutionWorkflowSource` materializes its plan rows and integration\n * topology from the execution store; coordination files are never read here.\n * `unreadable` distinguishes an unavailable/ambiguous authority from an\n * ordinary workspace with no active workflow so each gate preserves its\n * established refusal or no-op behavior.\n */\ninterface ActiveSnapshotRead {\n  /** The snapshot's plan rows ([] when the doc has no plans array); null when the read did not reach the rows. */\n  rows: Record<string, unknown>[] | null\n  /** The canonical snapshot (non-null exactly when `rows` is non-null). */\n  snapshot: WorkflowSnapshot | null\n  /** The selected workflow id (register key — the sibling scan skips it). */\n  workflowId: string | null\n  /** True when the lifecycle cannot be attributed (selection failure / unreadable / refused snapshot). */\n  unreadable: boolean\n}\n\nasync function activeSnapshotRows(harnessDir: string, hint?: SessionHint, activeSource?: ExecutionWorkflowSourceRead): Promise<ActiveSnapshotRead> {\n  try {\n    const source = activeSource ?? await readExecutionWorkflowSource({ harnessDir }, hint)\n    if (source.kind === 'error' && source.selection.kind === 'error' && source.selection.code === 'workflow.selection.no-active') {\n      return { rows: null, snapshot: null, workflowId: null, unreadable: false }\n    }\n    if (source.kind !== 'active') return { rows: null, snapshot: null, workflowId: null, unreadable: true }\n    const snapshot = source.snapshot as WorkflowSnapshot\n    return { rows: activeRowsOf(snapshot), snapshot, workflowId: source.workflowId, unreadable: false }\n  } catch {\n    return { rows: null, snapshot: null, workflowId: null, unreadable: true }\n  }\n}\n\n/**\n * L1 cross-plan isolation (engine `l1PreDispatchCheck` FULL input): when\n * the Assignment resolves a plan id AND the ACTIVE workflow snapshot\n * records a plan row scope (metadata.worktree_path + metadata.working_branch), the\n * gate assembles the full three-domain topology — the Git-derived main\n * worktree (`readMainWorktree` from the harness root: the main worktree of\n * the repo containing `{HARNESS_DIR}`; null is a failure row, never a\n * skip), the recorded residency expectation (the Assignment header's\n * `Main worktree branch` — the recorded value only, never the observed\n * branch — with the explicit `branch.base` fallback), the snapshot's\n * canonical integration topology (`integration_worktree_path` +\n * `branch.integration`), and the lifecycle-owned branches collected from\n * all active workflow snapshots (the governing one plus every sibling in\n * the v2 register — a scan refusal is a high violation, CLI parity, never\n * a silent skip).\n *\n * Fires ONLY when the row scope metadata is present (the \"L1 checks when\n * metadata present\" contract): no harness dir, unresolvable plan id,\n * missing/unattributable snapshot (selection failure, unreadable), or a\n * lease without the two path/branch fields all degrade to silence — the\n * exec-bound lease gate owns lease SHAPE errors (sdd\n * unverifiable/unreadable/plan-not-found) on the same verdict. Standalone\n * plans without integration fields run the main-vs-feature rows only (the\n * engine owns that distinction). The engine probes are subprocess-based\n * and fail closed.\n * @param harnessDir - the plugin's resolved `{HARNESS_DIR}` (null when none).\n * @param header - `assignmentHeaderRegion(assignmentText)`.\n * @param hint - the carrying session's selection hint (which lifecycle's\n *   snapshot carries the L1 metadata to compare against).\n */\nasync function worktreeL1Violations(\n  harnessDir: string | null,\n  header: string,\n  hint?: SessionHint,\n  activeSource?: ExecutionWorkflowSourceRead,\n): Promise<ValidationResult[]> {\n  if (harnessDir === null) return []\n  const planId = planIdOf(header)\n  if (planId === undefined || planId === '') return []\n  const read = await activeSnapshotRows(harnessDir, hint, activeSource)\n  if (read.rows === null || read.snapshot === null) return []\n  const row = read.rows.find((r) => r?.id === planId || r?.plan_id === planId)\n  const metadata = asRecord(row?.metadata)\n  const rowWorktreePath = typeof metadata?.worktree_path === 'string' ? metadata.worktree_path : undefined\n  const rowWorkingBranch = typeof metadata?.working_branch === 'string' ? metadata.working_branch : undefined\n  if (!rowWorktreePath || !rowWorkingBranch) return []\n  const snapshot = read.snapshot\n  try {\n    const graph = (await readExecutionState({ harnessDir })).data\n    const lifecycleSnapshots = graph.workflows.map((workflow) => ({\n      ...workflow.state,\n      plans: workflow.plans.map(({ plan }) => plan),\n    }))\n    const lifecycleBranches = collectActiveLifecycleBranches(lifecycleSnapshots)\n    const expectedMainBranch = assignmentHeaderValue(header, 'Main worktree branch')\n      ?? (typeof snapshot.branch?.base === 'string' ? snapshot.branch.base : '')\n    return l1PreDispatchCheck({\n      workflowType: snapshot.type,\n      integrationWorktreePath: typeof snapshot.integration_worktree_path === 'string' ? snapshot.integration_worktree_path : '',\n      integrationBranch: typeof snapshot.branch?.integration === 'string' ? snapshot.branch.integration : '',\n      mainWorktree: readMainWorktree(harnessDir),\n      expectedMainBranch,\n      lifecycleBranches,\n      rowWorktreePath,\n      rowWorkingBranch,\n      planId,\n      workflowId: snapshot.id,\n    }).violations\n  } catch (error) {\n    const refusal = refusalOf(error)\n    return [worktreeViolation(refusal.code, refusal.message, 'restore the ACTIVE store authority before writable dispatch')]\n  }\n}\n\n/**\n * P-b lease attribution for the workflow/ralph gate: the calling workspace's ACTIVE\n * workflow snapshot has any plan `InProgress` LACKING matching\n * recorded scope. Iterates ALL snapshot plan rows (no\n * Assignment header exists on the workflow/ralph branch — unlike\n * {@link leaseGateViolations} / {@link worktreeL1Violations}, which are\n * Assignment-keyed) and REUSES the named plumbing: the\n * {@link activeSnapshotRows} read (the v3 root `plans[]` → active snapshot\n * relocation) and the row's own `metadata.worktree_path` /\n * `metadata.working_branch` scope — an InProgress row that records no scope\n * is an uncovered row.\n *\n * Fail-open edges (the workflow branch never bricks fan-out): no harness dir\n * → nothing to attribute; missing status.json / no active lifecycle → no\n * plans to attribute; a SELECTION failure (v1/migration-required root) or a\n * THROWING read → `unreadable` (the caller emits ONE warn — a broken status\n * read must not brick fan-out, plan Clarify; P-a/P-c still run on the name\n * axis, which has no status dependency). A PARSEABLE-but-shape-invalid\n * snapshot (`plans` missing / non-array — e.g. a hand-edited `{}` or\n * `{\"plans\": {}}`) is `unreadable` TOO : the caller's ONE warn\n * gives it the same loudness as the throwing read, so a corrupt-but-parseable\n * snapshot cannot silently disable the P-b red line while looking like a\n * healthy read-only workspace. Fail-open is preserved in every case — P-b\n * degrades for the call, never bricks fan-out.\n *\n * @returns the first uncovered plan id (undefined = covered / nothing to\n *   attribute) + the unreadable flag.\n */\nasync function writableFanOutUncovered(\n  harnessDir: string | null,\n  hint?: SessionHint,\n): Promise<{ uncoveredPlanId?: string; unreadable: boolean; workflowId?: string; workflowDir?: string; selectedGeneration?: { storeId: string; epoch: number } }> {\n  if (harnessDir === null) return { unreadable: false }\n  // §5 the ONE route decision precedes every read (plan S4): while the\n  // execution authority is ACTIVE the root register and the workflow\n  // snapshots are retired, so the plan rows come from the DB state and the\n  // retired bytes are never consulted; a route that cannot be read degrades\n  // exactly like an unreadable document (one warn, fail-open), never a\n  // silent pass and never a file fallback.\n  let source: ExecutionWorkflowSourceRead\n  try {\n    source = await readExecutionWorkflowSource({ harnessDir }, hint)\n  } catch {\n    return { unreadable: true }\n  }\n  if (source.kind === 'unavailable') return { unreadable: source.code !== 'store.not-initialized' }\n  if (source.kind === 'error') {\n    return {\n      unreadable: source.selection.kind === 'error' && source.selection.code !== 'workflow.selection.no-active',\n    }\n  }\n  if (source.kind !== 'active') return { unreadable: true }\n  const rows = activeRowsOf(source.snapshot)\n  for (const row of rows) {\n    if (row === undefined || row.status !== 'InProgress') continue\n    const planId = typeof row.id === 'string' && row.id !== '' ? row.id\n      : typeof row.plan_id === 'string' && row.plan_id !== '' ? row.plan_id\n      : 'in-progress-plan'\n    const metadata = asRecord(row.metadata)\n    const scopeRecorded =\n      typeof metadata?.worktree_path === 'string' && metadata.worktree_path !== '' &&\n      typeof metadata?.working_branch === 'string' && metadata.working_branch !== ''\n    if (!scopeRecorded) return { uncoveredPlanId: planId, unreadable: false, workflowId: source.workflowId, workflowDir: join(harnessDir, source.dir), selectedGeneration: { storeId: source.storeId, epoch: source.epoch } }\n  }\n  return { unreadable: false, workflowId: source.workflowId, workflowDir: join(harnessDir, source.dir), selectedGeneration: { storeId: source.storeId, epoch: source.epoch } }\n}\n\n/**\n * The CALLING session's lineage position, as the execution context exposes it\n * (`session.header` — the same structural surface `sessionCwdOf` /\n * `sessionHintOf` read). `unresolvable` = the context carries no session at\n * all (the exec-less host `beforeDispatch` hook, a bare agent stub) — never\n * silently treated as a root.\n */\nfunction callingSessionOf(agent: unknown): 'root' | 'child' | 'unresolvable' {\n  const session = asRecord(asRecord(agent)?.session)\n  if (asRecord(session?.header) === undefined) return 'unresolvable'\n  return isRootLikeAgent(agent) ? 'root' : 'child'\n}\n\n/**\n * The anti-recursion CALLER for one dispatch — DERIVED from the calling\n * session, never invented:\n *\n * 1. a CHILD session (or a session the gate cannot read) → EMPTY, whatever\n *    `dispatchBinding` says, so the engine's\n *    `dispatch.anti-recursion.empty-binding` fails closed. A leaf must not\n *    dispatch, and no configuration may lift that;\n * 2. a ROOT session → an explicit `dispatchBinding` (settings / profile) wins\n *    verbatim, and an explicitly blank value stays blank and fails closed;\n * 3. no explicit value on a ROOT session → the coordinator identity\n *    (`ROOT_SESSION_DISPATCH_BINDING`) — a root session in this harness IS the\n *    coordinating agent, so this is an identity read, not a guess.\n *\n * Consequence: a deployment whose coordinator is NOT the root session cannot be\n * served by this field — the binding is a ROOT-session identity, never\n * inherited by a child.\n */\nexport function dispatchCallerOf(config: Config, agent: unknown): string {\n  if (callingSessionOf(agent) !== 'root') return ''\n  const explicit = liveConfigValue(config.dispatchBinding)\n  return explicit !== undefined ? explicit : ROOT_SESSION_DISPATCH_BINDING\n}\n\n/**\n * The dispatch-gate validation core — the engine's SINGLE dispatch-gate\n * composition (`dispatch.composeDispatchGate`, opencode/omp/CLI parity — the\n * SAME composition, so violation codes are identical by construction): shape\n * guard + field gate (read-only roles skip the branch gate) +\n * anti-recursion precheck (Config binding) + default-branch gate +\n * header-region enforcement. The dsh-side additions layer ON TOP: the\n * worktree L1/L2 checks (additive beyond opencode parity; the\n * lease gate is exec-bound and joins via {@link DshHostAdapter.dispatchGate}).\n * Extracted from `gateDispatch` so the `tools/pre-execute` listener and the\n * host adapter's `beforeDispatch` share ONE code path.\n *\n * Header-region scoping: the engine `assignmentHeaderRegion`\n * slice is computed ONCE and feeds the composition AND the worktree parsers\n * (fields, branch forms, direct-on exception, worktree tracks) — body-quoted\n * field examples after a `# Task` / `# Target` / `---` marker never leak\n * into the header fields the gate validates (the same discipline\n * enforcement / plan-id / lease already honor). Well-formed assignments\n * (fields in the header) slice to the full text, so their verdicts are\n * unchanged. The composition never throws: unexpected failures degrade to\n * the silent non-shaped result.\n *\n * @returns the violations plus the writable flag (false for read-only\n * roles — the listener feeds it to the lease gate).\n * @param callerAgent - the CALLING agent (`exec.agent` on the listener path,\n *   `undefined` on the exec-less host hook) — the session the caller identity\n *   is derived from ({@link dispatchCallerOf}).\n * @param hint - the carrying session's selection hint (the adapter derives\n *   it once per dispatch and shares it with the lease gate, the ledger\n *   record and every selection read below).\n */\nexport async function dispatchGateCore(\n  config: Config,\n  harnessDir: string | null,\n  prompt: string,\n  callerAgent: unknown,\n  hint?: SessionHint,\n  activeSource?: ExecutionWorkflowSourceRead,\n): Promise<{ violations: ValidationResult[]; writable: boolean | undefined }> {\n  const header = assignmentHeaderRegion(prompt)\n  const violations: ValidationResult[] = [...worktreeL2Violations(header), ...await worktreeL1Violations(harnessDir, header, hint, activeSource)]\n  // Read-only roles (scout/explore) skip the branch-form gate entirely.\n  const writable = isReadOnlyAssignmentRole(parseAssignmentFields(header).executeAs ?? '') ? false : undefined\n  // Engine single composition: shape guard + validateAssignmentFields\n  // (writable) + antiRecursionPrecheck (caller = the dispatching agent's own\n  // role, DERIVED from the calling session — an explicit binding is honoured\n  // only for a ROOT session, which otherwise reads as the coordinator; a\n  // child/unreadable session is always EMPTY; callerRequired keeps the 3.1.2\n  // fail-closed contract: an empty binding emits\n  // dispatch.anti-recursion.empty-binding) + default-branch gate (Assignment\n  // branch forms, else $MSTAR_WORKING_BRANCH; direct-on exception only when\n  // its branch is the one being checked) + header-region enforcement. Never\n  // throws. The caller is read LIVE — `dispatchBinding` is volatile (a\n  // settings save applies on the next dispatch) — and an explicitly blank\n  // value still fails closed.\n  violations.push(\n    ...composeDispatchGate(header, { caller: dispatchCallerOf(config, callerAgent), callerRequired: true, writable }).violations,\n  )\n  return { violations, writable }\n}\n\n/* ------------------------------- workflow/ralph branch ------------------------------- */\n\n/**\n * The workflow-gate input composed from one `workflow`/`ralph` tool call\n * : the tool name + the structural reads of\n * `meta` (workflow) / `objective` (ralph) + the in-flight call.\n */\nexport interface WorkflowGateInput {\n  /** The matched tool name (`'workflow'` | `'ralph'` — the gate name-guards on {@link DEFAULT_WORKFLOW_TOOLS} first). */\n  tool: 'workflow' | 'ralph'\n  /** `meta.name` for workflow calls — the P-a allowlist input; absent for ralph (no meta). */\n  metaName?: string\n  /** `objective` for ralph calls (objective-based ledger logging, P-b); absent for workflow. */\n  objective?: string\n  /** The in-flight tool call — Task 3 P-b lease attribution reads the calling agent/session off it. */\n  exec: ToolExecution\n  /**\n   * P-b lease attribution: the calling workspace's first\n   * `InProgress` plan lacking a recorded row scope (computed by\n   * {@link writableFanOutUncovered} from the status.json read through the\n   * contained resolver path — `preExecuteListener` already resolved the\n   * harness dir from the calling agent's session workspace). Undefined → no\n   * uncovered plan (allow axis). Applies to workflow AND ralph (P-b needs no\n   * `meta.name`).\n   */\n  uncoveredPlanId?: string\n}\n\n/**\n * Compose the {@link WorkflowGateInput} from one workflow/ralph tool call's\n * arguments — structural reads, NEVER throws (plan\n *   Task 1; args shapes architect-verified:\n * workflow `{ script, meta: { name, description, whenToUse?, phases? },\n * args? }` (`tool-workflow/src/index.ts:152-161`); ralph\n * `{ objective, maxRounds?, maxHandoffChars? }`\n * (`tool-ralph/src/index.ts:76,416-419`)). Returns undefined for malformed\n * args — workflow without a non-empty string `meta.name`, ralph without a\n * string `objective` — the fail-open + one-warn path.\n *\n * `meta.name` is NORMALIZED through {@link normalizeWorkflowName} (control\n * chars stripped) BEFORE the empty check — the P-c cache-key congruence\n * fold-in: the run-start observation (workflow-ledger.ts)\n * keys the ask cache with the SAME normalized name, so a control-char name\n * (`au\\u0000dit`) asks once and observes under one key instead of re-asking\n * forever. The length is NEVER capped here (the gate's identity axis is\n * uncapped — the ledger ROW display field is capped separately). A name\n * that is ONLY control characters normalizes to '' → malformed (fail-open),\n * matching the ledger's read boundary.\n */\nexport function workflowGateInputOf(exec: ToolExecution): WorkflowGateInput | undefined {\n  const args = asRecord(exec.arguments)\n  if (args === undefined) return undefined\n  if (exec.name === 'ralph') {\n    const objective = typeof args.objective === 'string' ? args.objective : undefined\n    if (objective === undefined) return undefined\n    return { tool: exec.name, objective, exec }\n  }\n  if (exec.name === 'workflow') {\n    const meta = asRecord(args.meta)\n    const metaName = typeof meta?.name === 'string' ? normalizeWorkflowName(meta.name) : undefined\n    if (meta === undefined || metaName === undefined || metaName === '') return undefined\n    return { tool: exec.name, metaName, exec }\n  }\n  return undefined\n}\n\n/**\n * The workflow/ralph gate branch. *\n * Name guard on the FIXED tool names ({@link DEFAULT_WORKFLOW_TOOLS}).\n * Non-workflow tools return undefined — the subagent branch owns them,\n * semantics unchanged.\n *\n * Mode short-circuit: `workflowGate: 'off'` → pass-through immediately, NO\n * verdict row (also precedes malformed-args handling — a malformed call\n * under `off` stays silent).\n *\n * Every other mode composes the {@link WorkflowGateInput} (plus the Task 3\n * P-b lease attribution: {@link writableFanOutUncovered} over the ACTIVE\n * workflow snapshot (`workflows/<id>/snapshot.json` — the v3 status.json\n * consumer; never the root v1 `plans[]`), resolved through the contained\n * resolver path)\n * and runs the policy ({@link workflowPolicy} — the SINGLE four-tier\n * decision point: P-b lease attribution + P-a name allowlist + P-c\n * first-seen ask). EVERY policy decision records ONE durable\n * `workflow-verdict` ledger row (verdict + metaName/objective +\n * mode, via the ledger plan's record path through\n * {@link DshHostAdapter.recordWorkflowVerdict}; the record is fully\n * contained and skipped when no harness dir resolved). The verdict maps to\n * the `tools/pre-execute` refusal vocabulary:\n *\n * - `allow` → undefined (delegate via `next()`; allowlisted names and ralph\n *   pass under any mode) + an `ok` verdict row.\n * - `warn` (default) → allowed WITH an advisory verdict row — the\n *   `mstar/dispatch-gate` advisory (the existing dispatch record path) +\n *   one warn (now centralized in the policy) + an\n *   `advisory` durable verdict row.\n * - `ask` → `{kind:'ask', reason}` returned WITHOUT `next()` (terminal —\n *   the registry services it through the approval waterfall; fail-closed\n *   upstream, this gate invents no answerer). P-c: first-seen names ask;\n *   resolved names (via {@link WorkflowAskCache.record}) use the cached\n *   decision, never a re-ask. The ask itself records an `ask` verdict row\n *   (pending resolution — the approval-allow outcome is observed later by\n *   the workflow-ledger consumer's run-start hook).\n * - `deny` → `{kind:'deny', reason}` WITHOUT `next()` (short-circuits the\n *   chain — the veto lands before any child starts) + a `denied` verdict\n *   row (no child ledger rows: the veto precedes start).\n *\n * Malformed args (workflow without `meta`/`meta.name`, ralph without a\n * string `objective`) → pass-through + ONE warn (fail-open, documented —\n * never crash a compliant call; under `hard` too) and NO verdict row (no\n * policy verdict was produced). NEVER throws: every read is structural.\n * @param hintReadOf - derives the carrying session's hint (once — the caller's\n *   memoized thunk) through the adapter, plus whether that session's durable\n *   binding could be read. P-b attributes the lease coverage of the BOUND\n *   lifecycle only; an unreadable binding store pauses the durable verdict row\n *   instead of attributing it to a lifecycle the session may not own. Called\n *   only after the tool-name/mode guards — the branch returns for every other\n *   tool without paying for a hint it would not read.\n */\nasync function gateWorkflow(\n  ctx: Context,\n  harnessDir: string | null,\n  config: Config,\n  adapter: DshHostAdapter,\n  exec: ToolExecution,\n  hintReadOf: () => SessionHintRead,\n): Promise<PreToolDecision | undefined> {\n  const toolName = exec.name\n  if (!(DEFAULT_WORKFLOW_TOOLS as readonly string[]).includes(toolName)) return undefined\n  const mode = config.workflowGate ?? 'warn'\n  if (mode === 'off') return undefined\n  const input = workflowGateInputOf(exec)\n  if (input === undefined) {\n    // Fail-open + ONE warn (plan Global Constraint — a malformed call must\n    // never crash a compliant run; the warn keeps the degraded control loud).\n    ctx.logger(DISPATCH_LOGGER).warn(\n      `workflow gate (${toolName}) (fail-open): malformed arguments — no ${toolName === 'ralph' ? 'objective' : 'meta'} to gate on; call allowed`,\n    )\n    return undefined\n  }\n  // P-b lease attribution : the status read through the contained\n  // resolver path — `harnessDir` was already resolved from the calling\n  // agent's session workspace by `preExecuteListener`, and the hint scopes\n  // the read to the lifecycle THIS session is bound to (an unbound session\n  // has no rows to attribute: the one-warn degrade below).\n  const pb = await writableFanOutUncovered(harnessDir, hintReadOf().hint)\n  if (pb.unreadable) {\n    // Fail-open + ONE warn ( Step 3 / Clarify — a broken status\n    // read must not brick fan-out): P-b is degraded for this call only;\n    // P-a/P-c (name-based, no status dependency) still run below.\n    const statusLabel = harnessDir === null ? STATUS_FILE : join(harnessDir, STATUS_FILE)\n    ctx.logger(DISPATCH_LOGGER).warn(\n      `workflow gate (${toolName}) (fail-open): cannot read ${statusLabel} — P-b lease attribution degraded; call allowed`,\n    )\n  }\n  const verdict = workflowPolicy(config, adapter.workflowAskCache, {\n    ...input,\n    ...(pb.uncoveredPlanId !== undefined ? { uncoveredPlanId: pb.uncoveredPlanId } : {}),\n  })\n  // — ONE durable verdict row per gated call (the ledger plan's\n  // record path, routed through the adapter so dispatch.ts keeps no runtime\n  // agent-flow edge; the record is fully contained — a failing ledger write\n  // never reaches the gate). The fail-open paths above (malformed args /\n  // unreadable status) record nothing — no policy verdict was produced;\n  // `off` short-circuited above. `harnessDir === null` (no workspace) skips\n  // the row — the same silent no-op as the dispatch record path.\n  const recordVerdict = (v: WorkflowVerdict, code?: string): void => {\n    // An unreadable binding store pauses the durable row: attributing it to\n    // whichever lifecycle resolves would write one session's verdict into\n    // another session's ledger. The policy decision itself already happened\n    // (the caller's allow/ask/deny is unaffected).\n    if (harnessDir === null) return\n    const hintRead = hintReadOf()\n    if (hintRead.kind === 'unavailable') return\n    if (pb.workflowId === undefined || pb.workflowDir === undefined || pb.selectedGeneration === undefined) return\n    adapter.recordWorkflowVerdict({\n      harnessDir,\n      workflowId: pb.workflowId,\n      exec,\n      tool: input.tool,\n      ...(input.metaName !== undefined ? { workflow: input.metaName } : {}),\n      ...(input.objective !== undefined ? { objective: input.objective } : {}),\n      mode,\n      verdict: v,\n      ...(code !== undefined ? { code } : {}),\n      resolvedWorkflowDir: pb.workflowDir,\n      selectedGeneration: pb.selectedGeneration,\n    })\n  }\n  switch (verdict.decision) {\n    case 'allow':\n      recordVerdict('ok')\n      return undefined\n    case 'warn':\n      // Advisory + ONE warn (decision now centralized in\n      // the policy). The advisory reuses the existing dispatch record path\n      // (the durable verdict row wiring). The violation code\n      // comes from the verdict — the gate never guesses which policy fired\n      // (P-a `workflow.name.unknown` vs P-b `workflow.lease.uncovered`).\n      ctx.logger(DISPATCH_LOGGER).warn(\n        `workflow gate (${toolName}) (advisory): ${verdict.reason}`,\n      )\n      ctx.emit('mstar/dispatch-gate', {\n        tool: toolName,\n        role: '',\n        result: {\n          ok: false,\n          violations: [{\n            ok: false,\n            severity: 'medium',\n            code: verdict.code,\n            message: verdict.reason,\n          }],\n        },\n        hard: false,\n      })\n      recordVerdict('advisory', verdict.code)\n      return undefined\n    case 'ask':\n      // Terminal decision — the registry services it via the approval\n      // waterfall (fail-closed upstream). Returned WITHOUT `next()` so no\n      // downstream listener can swallow the ask. The ask itself is a gated\n      // call → its verdict row carries `ask` (pending resolution).\n      recordVerdict('ask', verdict.code)\n      return { kind: 'ask', reason: verdict.reason }\n    case 'deny':\n      recordVerdict('denied', verdict.code)\n      ctx.logger(DISPATCH_LOGGER).error(`workflow gate (${toolName}) vetoed: ${verdict.reason}`)\n      return { kind: 'deny', reason: verdict.reason }\n  }\n}\n\n/**\n * The Assignment gate core shared by the subagent and the Agent Teams\n * branches (`gateDispatch` / {@link gateTeamDispatch}): header-region scoping,\n * the shape guard, ONE hard resolution, the adapter's shared dispatch-gate\n * core (lease + worktree L1/L2 + field + branch + anti-recursion), then the\n * warn advisory or the hard veto. `exec.name` is the ACTUAL carrier tool, so\n * both the deny reason and the advisory name the tool that carried the text\n * rather than assuming `subagent`.\n *\n * `prompt` is the raw carrier text — the header slice is computed here ONCE\n * and never fed back into the core (the adapter re-derives the same slice).\n */\nasync function gateAssignmentText(\n  ctx: Context,\n  harnessDir: string | null,\n  config: Config,\n  adapter: DshHostAdapter,\n  exec: ToolExecution,\n  prompt: string,\n  hintReadOf: () => SessionHintRead,\n): Promise<PreToolDecision | undefined> {\n  const toolName = exec.name\n  // Shape guard + advisory role read run on the header region:\n  // a `## Assignment` heading or field line quoted in the task body cannot\n  // shape a non-assignment prompt or leak into the advisory role.\n  const header = assignmentHeaderRegion(prompt)\n  if (!isAssignmentShaped(header)) return undefined\n\n  // The adapter owns the shared dispatch-gate core; the exec context is\n  // passed so the lease gate (session-id bound — see leaseGateViolations)\n  // joins the SAME verdict as the field/branch/anti-recursion checks.\n  // `hard` resolves ONCE per dispatch (\n  // : the adapter's record block and this gate decision share the\n  // single resolution instead of each re-reading the compass.\n  const hard = resolveDispatchHard(harnessDir, config, prompt)\n  const result = await adapter.dispatchGate(prompt, exec, hard, hintReadOf())\n  const verdict = applyEnforcement(result, { hard })\n  if (verdict.hardBlocked) {\n    ctx.logger(DISPATCH_LOGGER).error(\n      `subagent dispatch (${toolName}) vetoed (Enforcement: hard):\\n${verdict.violations.map(formatViolation).join('\\n')}`,\n    )\n    return { kind: 'deny', reason: denyReason(toolName, verdict) }\n  }\n  if (!verdict.ok) {\n    ctx.logger(DISPATCH_LOGGER).warn(\n      `subagent dispatch (${toolName}) (advisory):\\n${verdict.violations.map(formatViolation).join('\\n')}`,\n    )\n    const role = parseAssignmentFields(header).executeAs ?? ''\n    ctx.emit('mstar/dispatch-gate', { tool: toolName, role, result: verdict, hard })\n  }\n  return undefined\n}\n\n/**\n * The Agent Teams gate branch: resolve the carrier field for the fixed team\n * tools and route its text through the SAME core as `subagent`\n * ({@link gateAssignmentText}). A tool outside the fixed map, a missing or\n * non-string carrier (`team_task_update` status-only updates), or\n * non-Assignment text is a pure pass-through (undefined) — ordinary team\n * coordination text is never a false positive.\n *\n * The caller invokes this ONLY for a name {@link isTeamDispatchTool} owns, and\n * treats its result — `undefined` included — as TERMINAL for that name, so a\n * team name that also appears in `Config.dispatchTools` is never re-gated by\n * the subagent branch (one decision, one ledger record per call).\n */\nasync function gateTeamDispatch(\n  ctx: Context,\n  harnessDir: string | null,\n  config: Config,\n  adapter: DshHostAdapter,\n  exec: ToolExecution,\n  hintReadOf: () => SessionHintRead,\n): Promise<PreToolDecision | undefined> {\n  if (!isTeamDispatchTool(exec.name)) return undefined\n  const carrier = TEAM_DISPATCH_TOOLS[exec.name]\n  const text = asRecord(exec.arguments)?.[carrier]\n  if (typeof text !== 'string') return undefined\n  return gateAssignmentText(ctx, harnessDir, config, adapter, exec, text, hintReadOf)\n}\n\n/**\n * Run the dispatch gate over one delegation tool call (opencode\n * `validateDispatchAssignment` parity — the SAME engine fns, so violation\n * codes are identical). Returns the veto decision in hard mode, undefined\n * otherwise (warn mode: log + advisory emit; the caller delegates via `next()`).\n * Non-subagent tools, non-Assignment prompts and malformed payloads are pure\n * pass-through (undefined).\n */\nasync function gateDispatch(\n  ctx: Context,\n  harnessDir: string | null,\n  config: Config,\n  adapter: DshHostAdapter,\n  exec: ToolExecution,\n  readHint?: () => SessionHintRead,\n): Promise<PreToolDecision | undefined> {\n  const toolName = exec.name\n  // The carrying session's hint — derived ONCE per tool call through the\n  // adapter (the plugin's only owner of the durable binding store) and shared\n  // by the workflow branch, the dispatch branch's selection reads and the\n  // ledger record below. `dispatch.ts` therefore stays free of a runtime\n  // agent-flow / engine-status-store dependency (the adapter is the acyclic\n  // junction).\n  //\n  // LAZY on purpose: `tools/pre-execute` fires for EVERY tool call, and most\n  // calls are neither a workflow tool nor a dispatch tool — deriving eagerly\n  // would charge every one of them a binding-store read for a hint no branch\n  // reads. The thunk below memoizes the one derivation a gated call needs.\n  let derived: SessionHintRead | undefined\n  // The caller may own the memo (the listener shares ONE derivation with its\n  // catalog-registration veto — the D4 \"derived only where the gate reads it,\n  // once per call\" contract); otherwise this branch memoizes its own.\n  const hintReadOf: () => SessionHintRead = readHint ?? (() => (derived ??= adapter.sessionHintFor(exec.agent)))\n  // WORKFLOW/RALPH BRANCH — BEFORE the subagent prompt branch: `workflow`/`ralph` carry no\n  // `args.prompt`, so the prompt guard below would pass them through even\n  // if the names were added to the dispatch-tool match list (W4 double\n  // no-op). Keyed on the FIXED tool names — the workflow tools are gated\n  // by their own branch, never by `DEFAULT_DISPATCH_TOOLS` addition.\n  const workflowDecision = await gateWorkflow(ctx, harnessDir, config, adapter, exec, hintReadOf)\n  if (workflowDecision !== undefined) return workflowDecision\n  // AGENT TEAMS BRANCH — BEFORE and TERMINAL FOR the names it owns (the\n  // workflow branch above demonstrates the same placement): the team tools\n  // carry the Assignment text in a different argument field per tool and are\n  // gated by their own fixed-name branch, never by addition to\n  // `DEFAULT_DISPATCH_TOOLS`. Returning the branch result UNCONDITIONALLY —\n  // `undefined` included — is what makes the ownership terminal: a team name\n  // a caller also added to `Config.dispatchTools` can no longer fall through\n  // into the subagent match below and be gated (and ledger-recorded) twice.\n  if (isTeamDispatchTool(exec.name)) {\n    return gateTeamDispatch(ctx, harnessDir, config, adapter, exec, hintReadOf)\n  }\n  if (!(config.dispatchTools ?? [...DEFAULT_DISPATCH_TOOLS]).includes(toolName)) return undefined\n  const args = asRecord(exec.arguments)\n  const prompt = typeof args?.prompt === 'string' ? args.prompt : undefined\n  if (prompt === undefined) return undefined\n  return gateAssignmentText(ctx, harnessDir, config, adapter, exec, prompt, hintReadOf)\n}\n\n\n/**\n * `tools/pre-execute` listener. The waterfall refusal channel is the returned\n * decision: a deny is returned WITHOUT calling `next()` (short-circuits the\n * chain — downstream listeners and the registry default never run); every\n * other path calls `next()` to delegate (the registry's default is\n * `{ kind: 'allow' }`). Engine failures degrade to allow in BOTH modes (hard\n * gates are opt-in — an engine failure must not harden a workflow that was\n * soft; opencode parity) but the degrade is NEVER silent: the\n * catch path emits the plugin-owned `mstar/dispatch-gate` advisory with\n * `degraded: true` + an error log, so a hard deployment can detect a dead\n * control instead of only finding it in logs. `next()` itself is invoked\n * outside the guard so a downstream rejection propagates untouched.\n */\nexport async function preExecuteListener(\n  ctx: Context,\n  resolver: HarnessResolver,\n  config: Config,\n  adapter: DshHostAdapter,\n  exec: ToolExecution,\n  next: () => Promise<PreToolDecision>,\n): Promise<PreToolDecision> {\n  let veto: PreToolDecision | undefined\n  try {\n    const harnessDir = resolver.forAgent(exec.agent)\n    // One session-hint derivation for the gate reads in this call.\n    let hintRead: SessionHintRead | undefined\n    const readHint = (): SessionHintRead => (hintRead ??= adapter.sessionHintFor(exec.agent))\n    veto = await gateDispatch(ctx, harnessDir, config, adapter, exec, readHint)\n  } catch (error) {\n    ctx.logger(DISPATCH_LOGGER).error(`dispatch gate aborted (degraded, dispatch allowed): ${(error as Error).message}`)\n    try {\n      ctx.emit('mstar/dispatch-gate', { tool: exec.name, role: '', result: { ok: true, violations: [] }, hard: false, degraded: true })\n    } catch (emitError) {\n      // Best-effort observability: a throwing advisory consumer must not take\n      // the gate down with it (the error log above is the durable signal).\n      ctx.logger(DISPATCH_LOGGER).error(`dispatch gate degraded advisory emit failed: ${(emitError as Error).message}`)\n    }\n  }\n  return veto ?? await next()\n}\n\n/**\n * Rebuild the canonical Assignment HEADER text from parsed fields (the\n * engine's OWN header grammar — `parseAssignmentFields` reads exactly these\n * labels — so the engine parsers round-trip losslessly). Every typed\n